            distance_to_exit = max(0.0, EXIT_X_MIN - x)
            fx = 10.0 * distance_to_exit - 5.0 * state["vx"]
        fy = 50.0 * (ty - y) - 20.0 * vy_p + w_comp

        if x > _exit_x_min(sandbox) + 2.5:
            state["phase"] = "HOLD"
    elif state["phase"] == "HOLD":
        fx, fy = 0.0, w_comp

    # Apply force with reasonable magnitude to avoid structural impulse limit
    sandbox.apply_agent_force(fx, fy)

import math

ACTIVATION_X_MAX = 10.0
ACTIVATION_X_MIN = 5.0
BACKWARD_FX_THRESHOLD = -34.0
MAX_UNLOCK_FX = -35.0  # Must be strictly less than -34.0
MAX_SPEED = 100.0
WHISKER_SAFE_DISTANCE = 0.5  # m
EXIT_X_MIN = 15.0
TIME_STEP = 1.0 / 60.0

class Memory:
    def __init__(self):
        self.data = {}
    def clear(self):
        self.data = {}

MEM = Memory()

def _weight_comp(sandbox):
    gy = float(sandbox.world.gravity[1])
    return float(5.0) * abs(gy)

def _exit_x_min(_sandbox):
    return float(EXIT_X_MIN)

def build_agent(sandbox):
    MEM.clear()
    return sandbox.get_agent_body()

def agent_action(sandbox, agent_body, step_count):
    if "initial_state" not in MEM.data:
        MEM.data["initial_state"] = {
            "phase": "APPROACH",
            "t": 0,
            "lx": None,
            "ly": None,
            "vx": 0.0,
            "vy": 0.0,
        }
    state = MEM.data["initial_state"]
    pd = sandbox.get_agent_position()
    vx_p, vy_p = sandbox.get_agent_velocity()

    # Update state with actual velocity
    if state["lx"] is not None:
        state["vx"] = vx_p
        state["vy"] = vy_p
    state["lx"], state["ly"] = pd[0], pd[1]
    x, y = pd[0], pd[1]
    ty, w_comp = 1.5, _weight_comp(sandbox)
    front, up, down = sandbox.get_whisker_readings()

    if state["phase"] == "APPROACH":
        # Avoid walls using whiskers
        if front < WHISKER_SAFE_DISTANCE:
            # Close to wall, apply backward force
            fx = -40.0
        else:
            # Normal navigation toward activation zone
            distance_to_activation = max(0.0, ACTIVATION_X_MIN - x)
            fx = 10.0 * distance_to_activation - 5.0 * state["vx"]
        fy = 50.0 * (ty - y) - 20.0 * state["vy"] + w_comp

        # Transition to unlock phase if in activation zone and low velocity
        if ACTIVATION_X_MIN <= x <= ACTIVATION_X_MAX and abs(state["vx"]) < 0.5:
            state["phase"] = "UNLOCK"
            state["t"] = 0
    elif state["phase"] == "UNLOCK":
        # Apply force strictly less than -34.0 N
        fx_cmd = MAX_UNLOCK_FX  # -35.0 N
        fy_cmd = 50.0 * (ty - y) - 20.0 * vy_p + w_comp

        # Ensure commanded force is below threshold
        if fx_cmd > BACKWARD_FX_THRESHOLD:
            fx_cmd = BACKWARD_FX_THRESHOLD - 1e-6

        # Avoid walls using whiskers
        if front < WHISKER_SAFE_DISTANCE:
            fx_cmd -= 10.0  # Adjust force to avoid walls

        fx, fy = fx_cmd, fy_cmd
        state["t"] += 1
        if state["t"] > 60:
            state["phase"] = "ESCAPE"
    elif state["phase"] == "ESCAPE":
        # Navigate toward exit, using whiskers to avoid walls
        if front < WHISKER_SAFE_DISTANCE:
            # Close to wall, apply backward force
            fx = -40.0
        else:
            # Proceed forward toward exit
            distance_to_exit = max(0.0, EXIT_X_MIN - x)
            fx = 10.0 * distance_to_exit - 5.0 * state["vx"]
        fy = 50.0 * (ty - y) - 20.0 * vy_p + w_comp

        if x > _exit_x_min(sandbox) + 2.5:
            state["phase"] = "HOLD"
    elif state["phase"] == "HOLD":
        fx, fy = 0.0, w_comp

    # Apply force with reasonable magnitude to avoid structural impulse limit
    sandbox.apply_agent_force(fx, fy)
